package edu.casestudy.merkle.web;
import edu.casestudy.merkle.data.*;import edu.casestudy.merkle.data.Entities.*;import edu.casestudy.merkle.data.Repositories.*;import edu.casestudy.merkle.service.*;import edu.casestudy.merkle.core.*;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import java.util.*;import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api/v1") public class ApiController {final IntegrityService integrity;final CheckpointService checkpoints;final BenchmarkService benchmarks;final Datasets datasets;final Records records;final Audits audits;@org.springframework.beans.factory.annotation.Value("${app.demo-mode}")boolean demo; public ApiController(IntegrityService i,CheckpointService c,BenchmarkService b,Datasets d,Records r,Audits a){integrity=i;checkpoints=c;benchmarks=b;datasets=d;records=r;audits=a;}
 record DatasetInput(@NotBlank @Size(max=120) String name){} record RecordInput(@NotBlank @Size(max=20000) String payload){} record ProofInput(String leafHash,List<MerkleProof.Step> steps,String root){} record TreeNodeView(String hash,String recordId,Long position,TreeNodeView left,TreeNodeView right,boolean rightDuplicate){}
 @GetMapping("/overview") Map<String,Object> overview(){var all=datasets.findAll();long count=all.stream().mapToLong(d->records.findByDatasetIdOrderByPosition(d.id).size()).sum();var events=new ArrayList<Map<String,Object>>();for(var d:all)for(var a:audits.findTop50ByDatasetIdOrderByCreatedAtDesc(d.id))events.add(Map.of("dataset",d.name,"type",a.type,"details",a.details,"at",a.createdAt.toString()));events.sort((a,b)->String.valueOf(b.get("at")).compareTo(String.valueOf(a.get("at"))));return Map.of("datasetCount",all.size(),"recordCount",count,"recentEvents",events.stream().limit(12).toList());}@GetMapping("/datasets") List<Dataset> list(){return datasets.findAll();}@PostMapping("/datasets") @ResponseStatus(HttpStatus.CREATED) Dataset create(@RequestBody @jakarta.validation.Valid DatasetInput x){return integrity.create(x.name);}@PutMapping("/datasets/{id}") Dataset rename(@PathVariable UUID id,@RequestBody @jakarta.validation.Valid DatasetInput x){return integrity.rename(id,x.name);}@DeleteMapping("/datasets/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){datasets.delete(integrity.dataset(id));}
 @GetMapping("/datasets/{id}/records") List<DatasetRecord> recs(@PathVariable UUID id,@RequestParam(required=false)String q){return records.findByDatasetIdOrderByPosition(id).stream().filter(r->q==null||r.payload.toLowerCase().contains(q.toLowerCase())).toList();}@GetMapping(value="/datasets/{id}/export",produces="text/csv") ResponseEntity<byte[]> export(@PathVariable UUID id){var d=integrity.dataset(id);var out=new StringBuilder("position,record_id,payload\r\n");for(var r:records.findByDatasetIdOrderByPosition(id))out.append(r.position).append(',').append(csv(r.id.toString())).append(',').append(csv(safeForSpreadsheet(r.payload))).append("\r\n");var filename=d.name.replaceAll("[^a-zA-Z0-9._-]+","-").replaceAll("(^-|-$)","");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+(filename.isBlank()?"dataset":filename)+"-records.csv\"").contentType(org.springframework.http.MediaType.parseMediaType("text/csv;charset=UTF-8")).body(out.toString().getBytes(StandardCharsets.UTF_8));}@PostMapping("/datasets/{id}/records") @ResponseStatus(HttpStatus.CREATED) DatasetRecord add(@PathVariable UUID id,@RequestBody @jakarta.validation.Valid RecordInput x){return integrity.add(id,x.payload);}@PutMapping("/datasets/{id}/records/{record}") DatasetRecord update(@PathVariable UUID id,@PathVariable UUID record,@RequestBody @jakarta.validation.Valid RecordInput x){return integrity.update(id,record,x.payload);}@DeleteMapping("/datasets/{id}/records/{record}") @ResponseStatus(HttpStatus.NO_CONTENT) void del(@PathVariable UUID id,@PathVariable UUID record){integrity.delete(id,record);}
 @GetMapping("/datasets/{id}/tree") Map<String,Object> tree(@PathVariable UUID id){var t=integrity.tree(id);var source=records.findByDatasetIdOrderByPosition(id);var byId=new HashMap<String,DatasetRecord>();for(var r:source)byId.put(r.id.toString(),r);var response=new LinkedHashMap<String,Object>();response.put("root",t.root());response.put("trustedRoot",checkpoints.list(id).stream().findFirst().map(x->x.rootHash).orElse(null));response.put("tree",treeView(t.structure(),byId));response.put("recordCount",source.size());return response;}@PostMapping("/datasets/{id}/checkpoints") Checkpoint checkpoint(@PathVariable UUID id){return checkpoints.create(id);}@GetMapping("/datasets/{id}/checkpoints") List<Checkpoint> cp(@PathVariable UUID id){return checkpoints.list(id);}@PostMapping("/datasets/{id}/verify") Map<String,Object> verify(@PathVariable UUID id){return integrity.verify(id);}
 @GetMapping("/datasets/{id}/records/{record}/proof") Map<String,Object> proof(@PathVariable UUID id,@PathVariable UUID record){var tree=integrity.tree(id);var p=tree.proof(record);var current=p.leafHash();var reconstruction=new ArrayList<Map<String,Object>>();for(var step:p.steps()){current=HashUtils.hex(step.siblingOnLeft()?HashUtils.parent(HashUtils.unhex(step.siblingHash()),HashUtils.unhex(current)):HashUtils.parent(HashUtils.unhex(current),HashUtils.unhex(step.siblingHash())));reconstruction.add(Map.of("siblingHash",step.siblingHash(),"siblingOnLeft",step.siblingOnLeft(),"parentHash",current));}var trusted=checkpoints.list(id).stream().findFirst().map(x->x.rootHash).orElse(null);var out=new LinkedHashMap<String,Object>();out.put("proof",p);out.put("reconstruction",reconstruction);out.put("currentRoot",tree.root());out.put("trustedRoot",trusted);out.put("validAgainstCurrent",ProofVerifier.verify(p.leafHash(),p,tree.root()));out.put("validAgainstTrusted",trusted!=null&&ProofVerifier.verify(p.leafHash(),p,trusted));return out;}@PostMapping("/proofs/verify") Map<String,Boolean> verifyProof(@RequestBody ProofInput p){return Map.of("valid",ProofVerifier.verify(p.leafHash,new MerkleProof(p.leafHash,p.steps),p.root));}
 @PostMapping("/datasets/{id}/tamper/{record}") DatasetRecord tamper(@PathVariable UUID id,@PathVariable UUID record,@RequestBody @jakarta.validation.Valid RecordInput x){if(!demo)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"Demo mode disabled");var r=integrity.update(id,record,x.payload);integrity.audit(id,"DEMONSTRATION_TAMPER_MODIFIED",record.toString());return r;}@PostMapping("/datasets/{id}/tamper/insert") DatasetRecord tamperInsert(@PathVariable UUID id,@RequestBody @jakarta.validation.Valid RecordInput x){if(!demo)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"Demo mode disabled");var r=integrity.add(id,x.payload);integrity.audit(id,"DEMONSTRATION_TAMPER_INSERTED",r.id.toString());return r;}@PostMapping("/datasets/{id}/tamper/{record}/delete") @ResponseStatus(HttpStatus.NO_CONTENT) void tamperDelete(@PathVariable UUID id,@PathVariable UUID record){if(!demo)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"Demo mode disabled");integrity.delete(id,record);integrity.audit(id,"DEMONSTRATION_TAMPER_DELETED",record.toString());}@PostMapping("/datasets/{id}/restore") @ResponseStatus(HttpStatus.NO_CONTENT) void restore(@PathVariable UUID id){checkpoints.restore(id);}@GetMapping("/datasets/{id}/audit") List<Audit> audit(@PathVariable UUID id){return audits.findTop50ByDatasetIdOrderByCreatedAtDesc(id);}@PostMapping("/benchmarks") List<Map<String,Object>> bench(@RequestParam(defaultValue="0")@Max(20000) int size){return benchmarks.run(size);}
 private TreeNodeView treeView(MerkleNode node,Map<String,DatasetRecord> recordsById){if(node==null)return null;var record=node.recordId()==null?null:recordsById.get(node.recordId());boolean duplicate=node.left()!=null&&node.left()==node.right();return new TreeNodeView(node.hash(),node.recordId(),record==null?null:record.position,treeView(node.left(),recordsById),duplicate?null:treeView(node.right(),recordsById),duplicate);}private static String csv(String value){return "\""+value.replace("\"","\"\"")+"\"";}private static String safeForSpreadsheet(String value){return value.matches("^[=+@-].*")?"'"+value:value;}
 @ExceptionHandler({NoSuchElementException.class,IllegalArgumentException.class}) ResponseEntity<Map<String,String>> bad(RuntimeException x){return ResponseEntity.badRequest().body(Map.of("code","INVALID_REQUEST","message",x.getMessage()==null?"Invalid request":x.getMessage()));}}
